use crate::types::LineMetadata;use std::collections::VecDeque;
#[derive(Debug,Clone)]pub struct MetadataUndo{capacity:usize,undo:VecDeque<Vec<LineMetadata>>,redo:VecDeque<Vec<LineMetadata>>,before:Option<Vec<LineMetadata>>}
impl Default for MetadataUndo{fn default()->Self{Self::new(200)}}impl MetadataUndo{pub fn new(n:usize)->Self{Self{capacity:n.max(1),undo:VecDeque::new(),redo:VecDeque::new(),before:None}}pub fn begin(&mut self,b:&[LineMetadata]){if self.before.is_none(){self.before=Some(b.to_vec())}}pub fn end(&mut self,a:&[LineMetadata]){if let Some(b)=self.before.take(){if b!=a{self.undo.push_back(b);while self.undo.len()>self.capacity{self.undo.pop_front();}self.redo.clear();}}}pub fn record(&mut self,b:&[LineMetadata],a:&[LineMetadata]){self.begin(b);self.end(a)}pub fn undo(&mut self,current:&[LineMetadata])->Option<Vec<LineMetadata>>{let p=self.undo.pop_back()?;self.redo.push_back(current.to_vec());Some(p)}pub fn redo(&mut self,current:&[LineMetadata])->Option<Vec<LineMetadata>>{let n=self.redo.pop_back()?;self.undo.push_back(current.to_vec());Some(n)}pub fn can_undo(&self)->bool{!self.undo.is_empty()}pub fn can_redo(&self)->bool{!self.redo.is_empty()}}
